-- Three independently developed recipes informed by general low-FODMAP
-- ingredient and label-reading guidance. Not laboratory tested or certified.
begin;

insert into public.curated_recipes
  (title,summary,category,source_name,source_url,suitable_for_elimination,servings,preparation_minutes,ingredients,instructions,attribution_note,phase_note,published)
values
('Tempeh-rijstkom met ananas en gember','Kleurrijke plantaardige rijstkom met krokante tempeh, een bescheiden portie ananas en verse gember.','avondeten','Fodmap-Tracker','https://fodmaptracker20.vercel.app',true,4,35,E'300 g naturel tempeh, in blokjes\n280 g jasmijnrijst\n240 g paksoi, grof gesneden\n160 g groene paprika, in blokjes\n160 g wortel, in linten\n160 g verse ananas, in kleine stukken\n2 el knoflook-geïnfuseerde olie\n1½ el sojasaus zonder ui of knoflook\n2 tl verse gember, fijn geraspt\n2 tl rijstazijn\n1 tl sesamolie\n1 el sesamzaad',E'1. Kook de rijst volgens de verpakking en laat vijf minuten afgedekt rusten.\n2. Dep de tempeh droog en bak de blokjes in de geïnfuseerde olie rondom goudbruin.\n3. Voeg groene paprika, wortel en gember toe en roerbak drie minuten. Voeg daarna de paksoi toe en bak nog twee minuten.\n4. Meng sojasaus, rijstazijn en sesamolie. Schep dit samen met de ananas kort door de pan; verwarm maximaal één minuut.\n5. Verdeel rijst en tempehmengsel over vier kommen en strooi er sesam over.','Origineel recept, onafhankelijk ontwikkeld en geschreven door Fodmap-Tracker.','Eén kwart van de volledige pan is één portie. Kies naturel tempeh en controleer sojasaus op ui, knoflook, inuline en zoetstoffen. Ananas en groenten zijn bewust over vier porties verdeeld.',true),
('Krokante aubergine met citroenpolenta','Goudbruine aubergine met romige polenta, spinazie, tomaat en frisse citroen.','avondeten','Fodmap-Tracker','https://fodmaptracker20.vercel.app',true,4,45,E'400 g aubergine, in 12 plakken\n220 g fijne polenta\n800 ml water\n200 ml lactosevrije melk\n200 g babyspinazie\n160 g cherrytomaten, gehalveerd\n80 g glutenvrij paneermeel zonder ui of knoflook\n2 eieren\n50 g Parmezaan, fijn geraspt\n2½ el knoflook-geïnfuseerde olie\n1 citroen\n2 el bieslook\n1 tl gerookt paprikapoeder\nPeper en zout',E'1. Verwarm de oven voor op 220 °C. Meng paneermeel met paprikapoeder, peper en de helft van de Parmezaan.\n2. Klop de eieren los. Haal elke aubergineplak eerst door ei en daarna door het paneermeel. Leg op bakpapier, bestrijk dun met twee eetlepels olie en bak twintig tot vijfentwintig minuten; keer halverwege.\n3. Breng water en lactosevrije melk aan de kook. Klop de polenta er geleidelijk door en gaar volgens de verpakking. Roer de resterende Parmezaan en wat citroenrasp erdoor.\n4. Bak tomaat en spinazie kort in de resterende olie tot de spinazie slinkt.\n5. Verdeel polenta, groenten en drie aubergineplakken per bord. Werk af met bieslook en een beetje citroensap.','Origineel recept, onafhankelijk ontwikkeld en geschreven door Fodmap-Tracker.','Drie aubergineplakken met een kwart van de polenta en groenten vormen één portie. Controleer paneermeel en lactosevrije melk op inuline, cichoreiwortel, ui en knoflook.',true),
('Warme rijstpudding met kiwi en passievrucht','Zacht ontbijt van rijst en lactosevrije melk met kiwi, passievrucht en pompoenpitten.','ontbijt','Fodmap-Tracker','https://fodmaptracker20.vercel.app',true,4,35,E'160 g dessertrijst\n600 ml lactosevrije melk\n200 ml water\n2 groene kiwi''s\n2 passievruchten\n24 g pompoenpitten\n2 el tafelsuiker\n1 tl vanille-extract\n½ tl sinaasappelrasp\nSnuf zout',E'1. Breng rijst, melk, water en zout rustig aan de kook.\n2. Laat vijfentwintig tot dertig minuten op laag vuur garen en roer regelmatig tot de rijst romig en zacht is. Voeg zo nodig een scheut water toe.\n3. Roer suiker, vanille en sinaasappelrasp door de warme rijst.\n4. Schil de kiwi''s en snijd ze in plakjes. Halveer de passievruchten.\n5. Verdeel de pudding over vier kommen. Geef iedere kom een halve kiwi, een halve passievrucht en zes gram pompoenpitten.','Origineel recept, onafhankelijk ontwikkeld en geschreven door Fodmap-Tracker.','De fruit- en pittenporties zijn per kom afgemeten om stapeling te beperken. Controleer lactosevrije melk en vanille op inuline, FOS, cichoreiwortel en polyolen.',true)
on conflict (title) do update set
  summary=excluded.summary,category=excluded.category,source_name=excluded.source_name,source_url=excluded.source_url,
  suitable_for_elimination=excluded.suitable_for_elimination,servings=excluded.servings,preparation_minutes=excluded.preparation_minutes,
  ingredients=excluded.ingredients,instructions=excluded.instructions,attribution_note=excluded.attribution_note,
  phase_note=excluded.phase_note,published=true;

commit;
